command:
const size = await foundry.applications.api.DialogV2.wait({
    window: { title: "Change Token Size?" },
    content: "",
    buttons: [
        { action: "tiny", label: "Tiny", callback: () => 0.25 },
        { action: "small", label: "Small", callback: () => 0.5 },
        { action: "medium", label: "Medium", callback: () => 1 },
        { action: "large", label: "Large", callback: () => 2 },
        { action: "huge", label: "Huge", callback: () => 3 },
        { action: "gargantuan", label: "Gargantuan", callback: () => 4 },
        { action: "unit", label: "An Absolute Unit", callback: () => 8 }
    ],
    rejectClose: false
});

if (!size) return;

await token.document.update({ height: size, width: size });

switch(size) {
    case 0.25: await token.actor.update({"system.traits.size": "tiny"}); break;
    case 0.5: await token.actor.update({"system.traits.size": "sm"}); break;
    case 1: await token.actor.update({"system.traits.size": "med"}); break;
    case 2: await token.actor.update({"system.traits.size": "lg"}); break;
    case 3: await token.actor.update({"system.traits.size": "huge"}); break;
    case 4: await token.actor.update({"system.traits.size": "grg"}); break;
    case 8: await token.actor.update({"system.traits.size": "grg"}); break;
}
